mapper.select:
SELECT 
FROM company_visit_record cvr
JOIN company_users cu ON cu.id = cvr.company_id
JOIN teacher_users creator ON creator.id = cvr.creator_teacher_id


        cvr.company_id = #{companyId}


        AND cu.company_name LIKE CONCAT('%', #{companyName}, '%')


        AND YEAR(cvr.visit_date) = #{year}


        AND EXISTS (
            SELECT 1 FROM company_visit_participant cvp
            WHERE cvp.visit_record_id = cvr.id
              AND cvp.teacher_id = #{participantTeacherId}
        )


ORDER BY cvr.visit_date DESC, cvr.id DESC

SELECT FROM company_visit_participant cvp JOIN teacher_users tu ON tu.id = cvp.teacher_id WHERE cvp.visit_record_id IN
#{visitRecordId}
ORDER BY cvp.visit_record_id ASC, tu.name ASC, cvp.id ASC

SELECT company_id, COUNT(*) AS total_visit_count, SUM(CASE WHEN YEAR(visit_date) = #{selectedYear} THEN 1 ELSE 0 END) AS selected_year_visit_count, SUM(CASE WHEN YEAR(visit_date) = #{currentYear} THEN 1 ELSE 0 END) AS current_year_visit_count, MAX(visit_date) AS last_visit_date FROM company_visit_record WHERE company_id IN
#{companyId}
GROUP BY company_id

